  public void replayKnownUses(UUID execution, UUID attempt, Map<String,String> usage) {
    if (usage.isEmpty()) return;
    if (usage.values().stream().anyMatch(value -> !"USED".equals(value)))
      throw new IllegalArgumentException("Invalid positive secret usage report");
    var releases=jdbc.queryForList("SELECT * FROM studio_secret_use_audit WHERE execution_id=? AND attempt_id=? AND decision_stage='DISPATCH' AND outcome='RESOLVED'",execution,attempt.toString());
    var available=new java.util.HashSet<String>();
    releases.forEach(row -> available.add((String)row.get("secret_id")));
    if(!available.containsAll(usage.keySet()))throw new IllegalArgumentException("Missing scoped resolved secret release");
    for(var row:releases)if(usage.containsKey((String)row.get("secret_id")))
      audit.recordUsage(release(row),SecretUseAuditRecorder.UsageOutcome.USED);
  }

  public void replayTerminal(
      UUID execution, UUID attempt, Map<String, String> usage) {
    var rows =
        jdbc.queryForList(
            "SELECT * FROM studio_secret_use_audit WHERE execution_id=? AND attempt_id=? AND decision_stage='DISPATCH'",
            execution,
            attempt.toString());
    var declared = new java.util.HashSet<String>();
    rows.forEach(row -> declared.add((String) row.get("secret_id")));
    if (!declared.containsAll(usage.keySet()))
      throw new IllegalArgumentException("Invalid secret usage report");
    for (var row : rows)
      audit.recordUsage(
          release(row),
          usage.containsKey((String)row.get("secret_id")) ? SecretUseAuditRecorder.UsageOutcome.valueOf(usage.get((String)row.get("secret_id"))) : SecretUseAuditRecorder.UsageOutcome.UNKNOWN_OUTCOME);
  }

